//
// The statement, revocation list, flags and page derivation, each against the
// TypeScript originals' behaviour (fixtures generated by the shared package).

import XCTest
@testable import LiaisonShell

final class VerifyTests: XCTestCase {
    let signer = Signer()

    func trust(_ keys: [PinnedKey]? = nil, floor: [RevocationEntry] = [], list: RevocationList? = nil,
               bridge: Int = 1) -> Trust {
        Trust(keys: keys ?? [signer.pinned], floor: floor, list: list, bridgeVersion: bridge)
    }

    func refusal(_ result: Result<ShellStatement, Refusal>) -> Refusal? {
        if case let .failure(r) = result { return r }
        return nil
    }

    // MARK: Bytes TypeScript signed

    func testVerifiesAStatementSignedByTheSharedPackage() throws {
        let key = try XCTUnwrap(PinnedKey(keyId: SignedFixtures.keyId, base64: SignedFixtures.publicKey))
        let bytes = try XCTUnwrap(Data(base64Encoded: SignedFixtures.statement))
        let result = ShellVerifier.verify(bytes, sig: SignedFixtures.statementSig,
                                          trust: trust([key]), buildId: "0123456789abcdef")
        let statement = try result.get()
        XCTAssertEqual(statement.files["assets/é b.js"], String(repeating: "b", count: 64))
        XCTAssertEqual(statement.seq, 1_764_320_000)
        XCTAssertEqual(statement.bridgeIos, "^1")
    }

    func testReadsARevocationListAndDropsUnknownShellEntries() throws {
        let key = try XCTUnwrap(PinnedKey(keyId: SignedFixtures.keyId, base64: SignedFixtures.publicKey))
        let bytes = try XCTUnwrap(Data(base64Encoded: SignedFixtures.list))
        let list = try XCTUnwrap(Revocations.verify(bytes, sig: SignedFixtures.listSig, keys: [key]))
        XCTAssertEqual(list.seq, 7)
        XCTAssertEqual(list.entries.map(\.name), ["shell:native", "invoicing"])
        XCTAssertTrue(Revocations.belowShellFloor(list.entries, mode: "native", seq: 1_764_309_999))
        XCTAssertFalse(Revocations.belowShellFloor(list.entries, mode: "native", seq: 1_764_310_000))
        XCTAssertFalse(Revocations.belowShellFloor(list.entries, mode: "desktop", seq: 1))
    }

    func testReadsFleetFlags() throws {
        let key = try XCTUnwrap(PinnedKey(keyId: SignedFixtures.keyId, base64: SignedFixtures.publicKey))
        let bytes = try XCTUnwrap(Data(base64Encoded: SignedFixtures.flags))
        XCTAssertEqual(FleetFlags.verify(bytes, sig: SignedFixtures.flagsSig, keys: [key]),
                       FleetFlags(seq: 2, desktop: true, native: false))
        XCTAssertNil(FleetFlags.verify(bytes, sig: SignedFixtures.flagsSig, keys: [signer.pinned]))
    }

    func testPinnedKeysParse() {
        XCTAssertEqual(PinnedKeys.keys.count, PinnedKeys.raw.count)
        XCTAssertFalse(PinnedKeys.keys.isEmpty)
    }

    // MARK: Refusals

    func testHappyPath() throws {
        let (bytes, sig) = Build().signed(by: signer)
        XCTAssertEqual(try ShellVerifier.verify(bytes, sig: sig, trust: trust(), buildId: "0123456789abcdef").get().mode,
                       "native")
    }

    func testTamperedStatementIsRefused() {
        let (bytes, sig) = Build().signed(by: signer)
        var tampered = bytes
        let at = tampered.firstIndex(of: UInt8(ascii: "1"))!
        tampered[at] = UInt8(ascii: "2")
        XCTAssertNotNil(refusal(ShellVerifier.verify(tampered, sig: sig, trust: trust(), buildId: "0123456789abcdef")))
        XCTAssertNotEqual(refusal(ShellVerifier.verify(tampered, sig: sig, trust: trust(), buildId: "0123456789abcdef")),
                          nil)
    }

    func testBadSignature() {
        let (bytes, _) = Build().signed(by: signer)
        let other = Signer()
        XCTAssertEqual(refusal(ShellVerifier.verify(bytes, sig: other.sign(bytes), trust: trust(), buildId: "0123456789abcdef")),
                       .badSignature)
        XCTAssertEqual(refusal(ShellVerifier.verify(bytes, sig: "not base64", trust: trust(), buildId: "0123456789abcdef")),
                       .badSignature)
    }

    func testWrongKey() {
        let (bytes, sig) = Build().signed(by: signer)
        XCTAssertEqual(refusal(ShellVerifier.verify(bytes, sig: sig, trust: trust([Signer("other").pinned]),
                                                    buildId: "0123456789abcdef")), .unknownKey)
        XCTAssertEqual(refusal(ShellVerifier.verify(bytes, sig: sig, trust: trust([]), buildId: "0123456789abcdef")),
                       .noKeys)
    }

    func testWrongModeOrBuildIsRefused() {
        var desktop = Build()
        desktop.mode = "desktop"
        let (bytes, sig) = desktop.signed(by: signer)
        XCTAssertEqual(refusal(ShellVerifier.verify(bytes, sig: sig, trust: trust(), buildId: "0123456789abcdef")),
                       .wrongBuild)
        let (native, nativeSig) = Build().signed(by: signer)
        XCTAssertEqual(refusal(ShellVerifier.verify(native, sig: nativeSig, trust: trust(), buildId: "fedcba9876543210")),
                       .wrongBuild)
    }

    func testAnAppStatementNeverPassesAsAShellOne() {
        let app = signer.canonical([
            "v": 1, "keyId": signer.keyId, "name": "invoicing", "version": "1.0.0", "hostApi": "^1",
            "issuedAt": "2026-11-28", "sourceDigest": String(repeating: "a", count: 64),
            "sha256": ["manifest": String(repeating: "a", count: 64)],
        ])
        XCTAssertEqual(refusal(ShellVerifier.verify(app, sig: signer.sign(app), trust: trust(), buildId: "0123456789abcdef")),
                       .malformedStatement)
    }

    func testNonCanonicalBytesAreRefused() {
        let (bytes, _) = Build().signed(by: signer)
        let spaced = Data((String(data: bytes, encoding: .utf8)! + " ").utf8)
        XCTAssertEqual(refusal(ShellVerifier.verify(spaced, sig: signer.sign(spaced), trust: trust(), buildId: "0123456789abcdef")),
                       .malformedStatement)
    }

    func testPathsThatClimbOutAreRefused() {
        var build = Build()
        build.files["../escape.js"] = Data("x".utf8)
        let (bytes, sig) = build.signed(by: signer)
        XCTAssertEqual(refusal(ShellVerifier.verify(bytes, sig: sig, trust: trust(), buildId: "0123456789abcdef")),
                       .malformedStatement)
    }

    func testBelowTheCompiledFloor() {
        let (bytes, sig) = Build().signed(by: signer)
        let floor = [RevocationEntry(name: "shell:native", below: "1764320001")]
        XCTAssertEqual(refusal(ShellVerifier.verify(bytes, sig: sig, trust: trust(floor: floor), buildId: "0123456789abcdef")),
                       .belowFloor)
        let desktopFloor = [RevocationEntry(name: "shell:desktop", below: "1764320001")]
        XCTAssertNil(refusal(ShellVerifier.verify(bytes, sig: sig, trust: trust(floor: desktopFloor), buildId: "0123456789abcdef")))
    }

    func testRevokedByTheList() throws {
        let (bytes, sig) = Build().signed(by: signer)
        let (listBytes, listSig) = revocationList(signer, entries: [["name": "shell:native", "below": "1764320001"]])
        let list = try XCTUnwrap(Revocations.verify(listBytes, sig: listSig, keys: [signer.pinned]))
        XCTAssertEqual(refusal(ShellVerifier.verify(bytes, sig: sig, trust: trust(list: list), buildId: "0123456789abcdef")),
                       .revoked)
    }

    func testANumericShellFloorRefusesTheWholeList() {
        let (listBytes, listSig) = revocationList(signer, entries: [["name": "shell:native", "below": 5]])
        XCTAssertNil(Revocations.verify(listBytes, sig: listSig, keys: [signer.pinned]))
        let (unknown, unknownSig) = revocationList(signer, entries: [["name": "shell:watch", "below": 5]])
        XCTAssertEqual(Revocations.verify(unknown, sig: unknownSig, keys: [signer.pinned])?.entries, [])
    }

    func testBridgeRangeUnsatisfied() {
        var build = Build()
        build.ios = "^2"
        let (bytes, sig) = build.signed(by: signer)
        XCTAssertEqual(refusal(ShellVerifier.verify(bytes, sig: sig, trust: trust(), buildId: "0123456789abcdef")),
                       .bridge)
    }

    func testBridgeRangeGrammar() {
        let cases: [(String, Int, Bool)] = [
            ("^1", 1, true), ("^1", 2, false), ("^2", 1, false), ("1", 1, true), ("=1", 1, true), ("~1", 1, true),
            (">=1", 3, true), (">1", 1, false), ("<2", 1, true), ("<=1", 2, false), (">=1 <3", 2, true),
            (">=1 <3", 3, false), ("^1 || ^3", 3, true), ("^1 || ^3", 2, false), ("", 1, false), ("^x", 1, false),
            ("^01", 1, false), ("^1.2", 1, false), ("^1 ||", 1, false), ("0", 0, true),
        ]
        for (range, version, expected) in cases {
            XCTAssertEqual(BridgeRange.allows(range, version: version), expected, "\(range) vs \(version)")
        }
    }

    // MARK: The phone's page

    func testPageDerivationMatchesBootInjection() throws {
        XCTAssertFalse(pageCases.isEmpty)
        for (i, c) in pageCases.enumerated() {
            let input = String(data: try XCTUnwrap(Data(base64Encoded: c.input)), encoding: .utf8)!
            let page = try MobilePage.make(input)
            XCTAssertEqual(page.html, String(data: try XCTUnwrap(Data(base64Encoded: c.html)), encoding: .utf8), "case \(i)")
            let expected = c.files.mapValues { String(data: Data(base64Encoded: $0)!, encoding: .utf8)! }
            XCTAssertEqual(page.files, expected, "case \(i)")
        }
    }

    func testCanonicalStrings() {
        XCTAssertEqual(CanonicalJSON.encode(["b": 1, "a": "é\n\"\u{1}🚀"]), #"{"a":"é\n\"\u0001🚀","b":1}"#)
        XCTAssertNil(CanonicalJSON.encode(["a": 1.5]))
        XCTAssertNil(CanonicalJSON.value(Data(#"{"a":1.0}"#.utf8)))
    }
}
